// The band's own state, owned in one place (the one-owner principle,
// notes/meta/2026-10-12__22-48-40): the wait that ends a band mode, the watch that notices
// Esc took the keyboard back, the element the focus ring is on, the band's requestId, and
// whether the Esc reminder is owed. These were five module `let`s in register.tsx, written
// from the pane opening, the help, the band's keys, the focus and edit hooks, the band's
// render and the session start; here each write is a named method.

/** A timer as the engine hands it back: something that can be cancelled. */
export type Cancellable = { cancel: () => void }

export class BandState {
  private waitTimer: Cancellable | undefined
  private watchTimer: Cancellable | undefined
  // The band element the focus ring is on, as the ui.focus hook last saw it.
  private ringOn: string | undefined
  // The band's own requestId, as its render hook last saw it: $.ui.focus names the site
  // by it, to put the band's ring on the prompts field or the reading entry.
  private requestId: string | undefined
  // After a band action that finishes with the band still holding the keyboard (a jump,
  // `o`/`i`, the reading position, a promote), the person's next keys are usually their
  // prompt. The plugin can't hand the keyboard back (#24), so the first key the band does
  // not know says so, once per action, when "Keyboard after an action" is `input`.
  private escOwed = false

  /** (Re)start the wait that ends the band's mode; the previous wait is cancelled. */
  restartWait(start: () => Cancellable): void {
    this.waitTimer?.cancel()
    this.waitTimer = start()
  }
  stopWaiting(): void {
    this.waitTimer?.cancel()
    this.waitTimer = undefined
  }

  /** (Re)start the watch on the band's keyboard; the previous watch is cancelled. */
  startWatch(start: () => Cancellable): void {
    this.watchTimer?.cancel()
    this.watchTimer = start()
  }
  stopWatching(): void {
    this.watchTimer?.cancel()
    this.watchTimer = undefined
  }

  /** The band's mode ended: no wait, no watch, no ring. */
  ended(): void {
    this.stopWaiting()
    this.stopWatching()
    this.ringOn = undefined
  }

  /** A new conversation: what belonged to the last one goes (test-plan 2026-10-12__15-25-30, row M). */
  newConversation(): void {
    this.escOwed = false
    this.ringOn = undefined
  }

  get ring(): string | undefined {
    return this.ringOn
  }
  /** The ui.focus hook saw the ring move onto this element. */
  ringMoved(element: string): void {
    this.ringOn = element
  }

  get id(): string | undefined {
    return this.requestId
  }
  /** The band was drawn under this requestId. */
  drawn(requestId: string): void {
    this.requestId = requestId
  }

  get reminderOwed(): boolean {
    return this.escOwed
  }
  oweReminder(owed: boolean): void {
    this.escOwed = owed
  }
}

files.hooks/core/prompts/prompts-pane-state.ts:
// The prompts pane's own state, owned in one place (the one-owner principle,
// notes/meta/2026-10-12__22-48-40): the filter's words, the footnotes unfolded by hand,
// and the prompt the list centres on at its next draw. These were three module `let`s in
// register.tsx written from the number field, the pane's own buttons, the Esc hook, the
// pane opening and the conversation reset; here each write is a named method.

export class PromptsPaneState {
  // The prompts filter (#28): the words typed after `/` in the prompts pane's number field
  // (djdarcy, 2026-10-12: "Pane field only"); empty when no filter is active.
  private words = ''
  // The prompts whose footnotes the person unfolded (`.` or a press on the ellipsis row),
  // by number; folded is the default (the `footnotes` setting).
  private readonly open = new Set<number>()
  // The prompt the list should centre on at the pane's next draw (set when it opens).
  private centre: string | undefined

  get filter(): string {
    return this.words
  }
  /** The filter's words; false when they are the same as before (nothing to redraw). */
  setFilter(words: string): boolean {
    if (words === this.words) return false
    this.words = words
    return true
  }

  get unfolded(): ReadonlySet<number> {
    return this.open
  }
  unfold(n: number): void {
    this.open.add(n)
  }
  refold(n: number): void {
    this.open.delete(n)
  }
  /** `N.` in the field: unfold #N's footnotes, or fold them again. */
  toggleFold(n: number): void {
    if (this.open.has(n)) this.open.delete(n)
    else this.open.add(n)
  }

  /** The pane opened on this prompt: centre the list on it at the next draw. */
  centreOnNextDraw(uuid: string): void {
    this.centre = uuid
  }
  /** The prompt to centre on, once: read and cleared. */
  takeCentre(): string | undefined {
    const c = this.centre
    this.centre = undefined
    return c
  }

  /** A new conversation (/clear, /resume): its filter, folds and pending centre go. */
  newConversation(): void {
    this.words = ''
    this.open.clear()
    this.centre = undefined
  }
}

files.hooks/core/kit/drawn-messages.ts:
// The messages the render hooks have drawn since the plugin loaded: each one's text the
// first time it was drawn (a selection mark checks it landed in the right row; a refused
// jump quotes it), and the set of their ids' first four groups, kept as ids arrive. A
// drawn id may be the zero-tailed form of the real uuid, so "drawn?" is asked by the
// first four groups (core/kit/message-id.ts firstFour); the panes dim a row whose prompt
// has not been drawn since load ("never drawn since load" means what it says: a jump
// target Claude Code may refuse). Owned here; the render hooks note, the rest read.
import { firstFour } from './message-id.ts'

export class DrawnMessages {
  private readonly byId = new Map<string, string>()
  private readonly four = new Set<string>()

  /** A message drawn: kept once, with the text it was first drawn with. */
  note(id: string, text: string): void {
    if (this.byId.has(id)) return
    this.byId.set(id, text)
    this.four.add(firstFour(id))
  }

  /** Each drawn id with its text, read-only (the diagnostics read it whole). */
  get texts(): ReadonlyMap<string, string> {
    return this.byId
  }

  /** The drawn ids' first four groups, for the panes' dim rule. */
  get firstFours(): ReadonlySet<string> {
    return this.four
  }
}

